// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./ResolutionOracle.sol";

contract AMM is ERC2771Context, ReentrancyGuard {
    ERC20 public token;
    ResolutionOracle public oracle;

    // Fee configuration (0.5% = 50 basis points)
    uint256 public constant FEE_BPS = 50;
    uint256 public constant BPS_DENOMINATOR = 10000;
    address public constant FEE_COLLECTOR = 0xd59C4C70c10D2AF0D5bcefd9c64fe150bcd1350a;

    // Flash loan protection: minimum hold time before selling (blocks)
    uint256 public constant MIN_HOLD_BLOCKS = 2; // ~1 second on Sei (400ms blocks)
    mapping(address => uint256) public lastPurchaseBlock;

    string public name;
    uint256 public effectiveFrom;
    uint256 public effectiveTo;
    uint256 public resolutionOpen;
    uint256 public resolutionClose;

    mapping(address => uint256) public yesBalances; // Shares for yes
    mapping(address => uint256) public noBalances; // Shares for no
    uint256 public totalYes; // Total yes shares
    uint256 public totalNo; // Total no shares
    uint256 public totalYesTokens; // Actual token deposits for yes (for pricing)
    uint256 public totalNoTokens; // Actual token deposits for no (for pricing)

    mapping(address => bool) public hasClaimed;

    // Resolution state
    bool public resolved;
    bool public outcome; // true = yes wins, false = no wins
    uint256 public resolvedPoolBalance; // Snapshot of pool at resolution time

    // Events
    event SharesPurchased(address indexed buyer, bool isYes, uint256 amount, uint256 shares, uint256 newPrice);
    event SharesSold(address indexed seller, bool isYes, uint256 shares, uint256 amount, uint256 newPrice);
    event MarketResolved(bool outcome, uint256 yesVotes, uint256 noVotes);
    event Claimed(address indexed user, uint256 amount);
    event FeeCollected(address indexed buyer, uint256 feeAmount);

    constructor(
        address _trustedForwarder,
        ERC20 _token,
        ResolutionOracle _oracle,
        string memory _name,
        uint256 _effectiveFrom,
        uint256 _effectiveTo,
        uint256 _resolutionOpen,
        uint256 _resolutionClose
    ) ERC2771Context(_trustedForwarder) {
        require(_effectiveFrom < _effectiveTo, "Invalid trading period");
        require(_effectiveTo <= _resolutionOpen, "Trading must end before resolution");
        require(_resolutionOpen < _resolutionClose, "Invalid resolution period");

        token = _token;
        oracle = _oracle;
        name = _name;
        effectiveFrom = _effectiveFrom;
        effectiveTo = _effectiveTo;
        resolutionOpen = _resolutionOpen;
        resolutionClose = _resolutionClose;
    }

    modifier duringTradingPeriod() {
        require(
            block.timestamp >= effectiveFrom && block.timestamp <= effectiveTo,
            "Trading outside effective period"
        );
        _;
    }

    modifier canSell() {
        require(
            block.number >= lastPurchaseBlock[_msgSender()] + MIN_HOLD_BLOCKS,
            "Must wait before selling (flash loan protection)"
        );
        _;
    }

    function price() public view returns (uint256) {
        uint256 totalTokenDeposits = totalYesTokens + totalNoTokens;
        if (totalTokenDeposits == 0) {
            return 5e17; // Default 50% when no liquidity
        }
        // Price is the ratio of yes token deposits to total token deposits
        return (totalYesTokens * 1e18) / totalTokenDeposits;
    }

    function buyYes(uint256 amount) public duringTradingPeriod nonReentrant {
        require(amount > 0, "Amount must be greater than 0");
        token.transferFrom(_msgSender(), address(this), amount);

        // Deduct 0.5% fee
        uint256 fee = (amount * FEE_BPS) / BPS_DENOMINATOR;
        uint256 netAmount = amount - fee;

        // Transfer fee to collector
        if (fee > 0) {
            token.transfer(FEE_COLLECTOR, fee);
            emit FeeCollected(_msgSender(), fee);
        }

        uint256 currentPrice = price();

        // Calculate shares based on current price
        // Lower price = more shares per token (rewarding early buyers)
        uint256 shares;
        if (totalYesTokens == 0 && totalNoTokens == 0) {
            // First purchase: 1 share per token
            shares = netAmount;
        } else if (currentPrice == 0) {
            // Price is 0 (all No): buying Yes is very cheap
            shares = netAmount * 10; // 10x shares at 0%
        } else {
            // Shares = amount / currentPrice (normalized)
            // At 50% price: 2 shares per token
            // At 10% price: 10 shares per token
            shares = (netAmount * 1e18) / currentPrice;
        }

        yesBalances[_msgSender()] += shares;
        totalYes += shares;
        totalYesTokens += netAmount;

        // Record purchase block for flash loan protection
        lastPurchaseBlock[_msgSender()] = block.number;

        emit SharesPurchased(_msgSender(), true, netAmount, shares, price());
    }

    function buyNo(uint256 amount) public duringTradingPeriod nonReentrant {
        require(amount > 0, "Amount must be greater than 0");
        token.transferFrom(_msgSender(), address(this), amount);

        // Deduct 0.5% fee
        uint256 fee = (amount * FEE_BPS) / BPS_DENOMINATOR;
        uint256 netAmount = amount - fee;

        // Transfer fee to collector
        if (fee > 0) {
            token.transfer(FEE_COLLECTOR, fee);
            emit FeeCollected(_msgSender(), fee);
        }

        uint256 currentPrice = price();
        uint256 noPrice = 1e18 - currentPrice;

        // Calculate shares based on no price (inverse of yes price)
        uint256 shares;
        if (totalYesTokens == 0 && totalNoTokens == 0) {
            // First purchase: 1 share per token
            shares = netAmount;
        } else if (noPrice == 0) {
            // No price is 0 (all Yes): buying No is very cheap
            shares = netAmount * 10; // 10x shares at 0%
        } else {
            // Shares = amount / noPrice (normalized)
            shares = (netAmount * 1e18) / noPrice;
        }

        noBalances[_msgSender()] += shares;
        totalNo += shares;
        totalNoTokens += netAmount;

        // Record purchase block for flash loan protection
        lastPurchaseBlock[_msgSender()] = block.number;

        emit SharesPurchased(_msgSender(), false, netAmount, shares, price());
    }

    function sellYes(uint256 shares) public duringTradingPeriod canSell nonReentrant {
        require(shares > 0, "Shares must be greater than 0");
        require(yesBalances[_msgSender()] >= shares, "Insufficient shares");
        require(totalYes > 0, "No shares to sell");

        uint256 currentPrice = price();

        // Calculate token amount based on current price and share proportion
        // amount = shares * currentPrice / 1e18
        uint256 amount = (shares * currentPrice) / 1e18;
        require(amount > 0, "Amount too small");
        require(amount <= totalYesTokens, "Insufficient liquidity");

        yesBalances[_msgSender()] -= shares;
        totalYes -= shares;
        totalYesTokens -= amount;

        token.transfer(_msgSender(), amount);

        emit SharesSold(_msgSender(), true, shares, amount, price());
    }

    function sellNo(uint256 shares) public duringTradingPeriod canSell nonReentrant {
        require(shares > 0, "Shares must be greater than 0");
        require(noBalances[_msgSender()] >= shares, "Insufficient shares");
        require(totalNo > 0, "No shares to sell");

        uint256 currentPrice = price();
        uint256 noPrice = 1e18 - currentPrice;

        // Calculate token amount based on no price and share proportion
        uint256 amount = (shares * noPrice) / 1e18;
        require(amount > 0, "Amount too small");
        require(amount <= totalNoTokens, "Insufficient liquidity");

        noBalances[_msgSender()] -= shares;
        totalNo -= shares;
        totalNoTokens -= amount;

        token.transfer(_msgSender(), amount);

        emit SharesSold(_msgSender(), false, shares, amount, price());
    }

    function resolve() public {
        require(block.timestamp >= resolutionClose, "Resolution period not ended");
        require(!resolved, "Already resolved");

        uint256 yesVotes = oracle.yesVotesTotal(address(this));
        uint256 noVotes = oracle.noVotesTotal(address(this));

        // Handle no-votes case: set resolved flag for proportional refunds
        if (yesVotes == 0 && noVotes == 0) {
            resolved = true;
            outcome = false; // Doesn't matter for refunds
            resolvedPoolBalance = token.balanceOf(address(this)); // Snapshot for refunds
            emit MarketResolved(false, 0, 0); // Emit with 0 votes
            return;
        }

        resolved = true;
        outcome = yesVotes > noVotes;
        resolvedPoolBalance = token.balanceOf(address(this)); // Snapshot pool balance

        emit MarketResolved(outcome, yesVotes, noVotes);
    }

    function getOutcome() public view returns (bool yesWins, bool isResolved) {
        if (!resolved) {
            // Check if we can determine outcome from oracle
            if (block.timestamp >= resolutionClose) {
                uint256 yesVotes = oracle.yesVotesTotal(address(this));
                uint256 noVotes = oracle.noVotesTotal(address(this));
                if (yesVotes > 0 || noVotes > 0) {
                    return (yesVotes > noVotes, true);
                }
            }
            return (false, false);
        }
        return (outcome, true);
    }

    function calculateClaim(address user) public view returns (uint256) {
        require(block.timestamp >= resolutionClose, "Resolution not yet closed");

        if (hasClaimed[user]) {
            return 0;
        }

        // Use snapshotted pool balance if resolved, otherwise current balance for preview
        uint256 totalPoolBalance = resolved ? resolvedPoolBalance : token.balanceOf(address(this));
        if (totalPoolBalance == 0) {
            return 0;
        }

        // Get outcome from oracle
        uint256 yesVotes = oracle.yesVotesTotal(address(this));
        uint256 noVotes = oracle.noVotesTotal(address(this));

        if (yesVotes == 0 && noVotes == 0) {
            // No resolution votes - refund proportionally
            uint256 userYesTokens = (yesBalances[user] * totalYesTokens) / (totalYes > 0 ? totalYes : 1);
            uint256 userNoTokens = (noBalances[user] * totalNoTokens) / (totalNo > 0 ? totalNo : 1);
            return userYesTokens + userNoTokens;
        }

        bool yesWins = yesVotes > noVotes;

        uint256 userShares;
        uint256 totalWinningShares;

        if (yesWins) {
            userShares = yesBalances[user];
            totalWinningShares = totalYes;
        } else {
            userShares = noBalances[user];
            totalWinningShares = totalNo;
        }

        if (totalWinningShares == 0 || userShares == 0) {
            return 0;
        }

        // Distribute the entire pool proportionally based on shares
        return (userShares * totalPoolBalance) / totalWinningShares;
    }

    function claim() public nonReentrant {
        require(block.timestamp >= resolutionClose, "Resolution not yet closed");
        require(!hasClaimed[_msgSender()], "Already claimed");

        // Ensure market is resolved
        if (!resolved) {
            resolve();
        }

        uint256 claimable = calculateClaim(_msgSender());
        require(claimable > 0, "No claimable amount");

        hasClaimed[_msgSender()] = true;
        token.transfer(_msgSender(), claimable);

        emit Claimed(_msgSender(), claimable);
    }

    // View functions for frontend
    function getMarketInfo() public view returns (
        string memory marketName,
        uint256 currentPrice,
        uint256 totalYesShares,
        uint256 totalNoShares,
        uint256 totalYesDeposits,
        uint256 totalNoDeposits
    ) {
        return (
            name,
            price(),
            totalYes,
            totalNo,
            totalYesTokens,
            totalNoTokens
        );
    }

    function getMarketTiming() public view returns (
        uint256 tradingStart,
        uint256 tradingEnd,
        uint256 resolutionStart,
        uint256 resolutionEnd,
        bool isResolved,
        bool marketOutcome
    ) {
        (bool _outcome, bool _isResolved) = getOutcome();
        return (
            effectiveFrom,
            effectiveTo,
            resolutionOpen,
            resolutionClose,
            _isResolved,
            _outcome
        );
    }

    function getUserPosition(address user) public view returns (
        uint256 yesShares,
        uint256 noShares,
        uint256 claimableAmount,
        bool claimed
    ) {
        uint256 claimable = 0;
        if (block.timestamp >= resolutionClose) {
            claimable = calculateClaim(user);
        }
        return (
            yesBalances[user],
            noBalances[user],
            claimable,
            hasClaimed[user]
        );
    }

    function canUserSell(address user) public view returns (bool) {
        return block.number >= lastPurchaseBlock[user] + MIN_HOLD_BLOCKS;
    }
}

